using System.Collections.Generic;
using UnityEngine;

namespace LittleRoad
{
    // The new Bayview (docs/79), behind --new-bayview: a bigger harbour island built from the plan in NewBayviewPlan.cs
    // (generated by tools/bayview_plan.py). Stage 1, the island in grey: its land, the Harbour Loop with its elevation, the
    // gravel lane and the link to the causeway. The old island's code is untouched; CoastalLandscape asks here for heights
    // when the flag is on, and `new Circuit()` returns this loop, so every system that takes "the island" from it (races,
    // free-roam recovery, the mainland's junction) follows. The mainland contract holds: the causeway's foot, the Halt
    // quay and the rail loop stay where Hillcrest expects them.
    public static class NewBayview
    {
        // (once: Has reads the command line, and the land asks per cell. The new Bayview is the game's since 20 Oct, --old-bayview
        //  for the old island; the editor's checks and bakes still build the old one unless asked, --new-bayview)
        public static bool On=>on??=Application.isEditor?RaceTrial.Has("--new-bayview"):!RaceTrial.Has("--old-bayview");static bool? on;
        public static readonly Vector3 Spawn=new(62,1.2f,-40);   // (on the Pit Stop's forecourt, by the start straight)
        public static readonly Vector3 PitStopSite=new(62,FrontY,-24);public const float PitStopYaw=180;   // (facing the start straight)
        // The harbour front's town row: the loop's arc where the road runs round the harbour (its inland, left-hand side).
        public const float TownFrom=894,TownTo=1035,TownBack=26;   // (metres along the loop: re-measure if the plan changes)
        public static Vector3 Cafe,Paint;public static float CafeYaw,PaintYaw;   // (where the town's shop residents stand: set when the town is built)
        public const float FrontY=1f;public const float SeaFloor=-44f;   // (the deep sea floor, 32 m under the water)                              // (the harbour front and the start straight: just above the quays)

        // ---- the land
        static float Blend(float a,float b,float x)=>Mathf.SmoothStep(0,1,Mathf.InverseLerp(a,b,x));
        // Signed distance to the coast: positive inland, negative out at sea.
        public static float CoastDistance(float x,float z)
        {
            var c=NewBayviewPlan.Coast;var p=new Vector2(x,z);float best=float.MaxValue;bool inside=false;
            for(int i=0,j=c.Length-1;i<c.Length;j=i++) {
                Vector2 a=c[j],b=c[i];var ab=b-a;float t=Mathf.Clamp01(Vector2.Dot(p-a,ab)/Mathf.Max(ab.sqrMagnitude,1e-6f));best=Mathf.Min(best,(a+ab*t-p).magnitude);
                if((a.y>z)!=(b.y>z)&&x<(b.x-a.x)*(z-a.y)/(b.y-a.y)+a.x)inside=!inside;
            }
            return inside?best:-best;
        }
        static float PolylineDistance(Vector2[] line,Vector2 p)
        {
            float best=float.MaxValue;
            for(int i=1;i<line.Length;i++){var a=line[i-1];var ab=line[i]-a;float t=Mathf.Clamp01(Vector2.Dot(p-a,ab)/Mathf.Max(ab.sqrMagnitude,1e-6f));best=Mathf.Min(best,(a+ab*t-p).magnitude);}
            return best;
        }
        // The land without its roads: a plateau rising inland to the windmill's summit, cliffs on the north and west, a
        // long gentle beach on the east, the harbour front a flat apron just above the water.
        public static float Base(float x,float z)
        {
            float d=CoastDistance(x,z);var w=NewBayviewPlan.Windmill;
            float n=Mathf.PerlinNoise((x+910)*.021f,(z+330)*.021f);
            float hill=24*Mathf.Exp(-((x-w.x)*(x-w.x)+(z-w.y)*(z-w.y))/(2*78f*78f));
            float top=2.5f+6*Blend(0,110,d)+(n-.5f)*5+hill;
            bool beach=x>95&&z<40&&z>-60;
            float shore=Blend(0,beach?42:9+n*6,d);                     // (cliffs: 9-15 m to full height; the beach: 42 m)
            float h=Mathf.Lerp(-16,top,shore);
            // The harbour front: a flat apron at quay level from the bay's shore (its quay edge drops straight to the water)
            // back past the road and the town row, the hill rising behind
            float front=1-Blend(36,52,PolylineDistance(NewBayviewPlan.Harbour,new Vector2(x,z)));
            if(d>0)h=Mathf.Lerp(h,FrontY,front);
            // The sea floor shelves away offshore and is deep (the water's colour saturates) by the land grid's edge: a
            // shallow shelf to the grid's edge, and no floor past it, showed as a pale rectangle with straight sides on
            // the open sea (street review R1-1, docs/80). The grid is ±270 x ±252 m (CoastalLandscape.LandNX/NZ).
            if(d<0) {
                float border=Mathf.Min(270-Mathf.Abs(x),252-Mathf.Abs(z));
                float deep=Mathf.Max(Blend(60,150,-d),1-Blend(4,40,border));deep*=Blend(0,30,BasinDistance(x,z));h=Mathf.Min(h,Mathf.Lerp(h,SeaFloor,deep));   // (the basin inside the arms stays one shallow turquoise)
            }
            return h;
        }

        // Inside the harbour: the shore, the west arm out to its head, across the mouth, the quay arm back to the shore.
        static Vector2[] basin;
        // (0 inside the basin; outside, the distance to its edge: the shelving blends in across the mouth, no straight cut)
        static float BasinDistance(float x,float z){if(InBasin(x,z))return 0;var q=new Vector2(x,z);var closed=new Vector2[basin.Length+1];basin.CopyTo(closed,0);closed[^1]=basin[0];return PolylineDistance(closed,q);}
        static bool InBasin(float x,float z)
        {
            if(basin==null){var l=new List<Vector2>(NewBayviewPlan.Harbour);l.AddRange(NewBayviewPlan.WestArm);var q=new List<Vector2>(NewBayviewPlan.QuayArm);q.Reverse();l.AddRange(q);basin=l.ToArray();}
            bool inside=false;for(int i=0,j=basin.Length-1;i<basin.Length;j=i++){Vector2 a=basin[j],c=basin[i];if((a.y>z)!=(c.y>z)&&x<(c.x-a.x)*(z-a.y)/(c.y-a.y)+a.x)inside=!inside;}
            return inside;
        }
        // ---- the Harbour Loop: Catmull-Rom through the plan's points (36 a span, as the old island's), its height the land's
        // smoothed along it, held at the harbour front's level along the south.
        static Vector3[] loop;
        public static Vector3[] LoopPoints()
        {
            if(loop!=null)return loop;
            // (centripetal, sampled about every 1.2 m: the plan's arcs space their points closer than its straights, and a uniform
            //  Catmull-Rom kinks where the spacing changes; tools/bayview_plan.py draws the same curve)
            var c=NewBayviewPlan.Loop;int N=c.Length;var list=new List<Vector3>();
            for(int s=0;s<N;s++) {
                Vector2 p0=c[(s+N-1)%N],p1=c[s],p2=c[(s+1)%N],p3=c[(s+2)%N];
                float t0=0,t1=t0+Mathf.Sqrt(Mathf.Max(Vector2.Distance(p0,p1),1e-3f)),t2=t1+Mathf.Sqrt(Mathf.Max(Vector2.Distance(p1,p2),1e-3f)),t3=t2+Mathf.Sqrt(Mathf.Max(Vector2.Distance(p2,p3),1e-3f));
                int m=Mathf.Max(4,Mathf.CeilToInt(Vector2.Distance(p1,p2)/1.2f));
                for(int k=0;k<m;k++) {
                    float t=t1+(t2-t1)*k/m;
                    Vector2 L(Vector2 a,Vector2 b,float ta,float tb)=>((tb-t)*a+(t-ta)*b)/(tb-ta);
                    Vector2 a1=L(p0,p1,t0,t1),a2=L(p1,p2,t1,t2),a3=L(p2,p3,t2,t3);var q=L(L(a1,a2,t0,t2),L(a2,a3,t1,t3),t1,t2);
                    list.Add(new Vector3(q.x,0,q.y));
                }
            }
            var pts=list.ToArray();int n=pts.Length;
            var y=new float[n];for(int i=0;i<n;i++)y[i]=Mathf.Max(Base(pts[i].x,pts[i].z),.6f);
            // (held at the front's level along the start straight and all round the harbour, so the town stands on the quay)
            y=Smooth(y,30);for(int i=0;i<n;i++){float hold=Mathf.Max(1-Blend(-46,-22,pts[i].z),1-Blend(36,56,PolylineDistance(NewBayviewPlan.Harbour,new Vector2(pts[i].x,pts[i].z))));y[i]=Mathf.Lerp(y[i],FrontY,hold);}
            y=Smooth(y,12);
            for(int i=0;i<n;i++)pts[i].y=y[i];
            return loop=pts;
        }
        static float[] Smooth(float[] v,int r)
        {
            int n=v.Length;var o=new float[n];
            for(int i=0;i<n;i++){float s=0;for(int k=-r;k<=r;k++)s+=v[(i+k+n)%n];o[i]=s/(2*r+1);}
            return o;
        }
        // ---- the gravel lane: an open spline, its height the land's smoothed and joined to the loop's at both ends
        static Vector3[] gravel;
        public static Vector3[] GravelPoints(Circuit track)
        {
            if(gravel!=null)return gravel;
            var c=NewBayviewPlan.Gravel;var pts=new List<Vector3>();
            for(int s=0;s+1<c.Length;s++)for(int k=0;k<24;k++){float t=k/24f;Vector2 a=c[Mathf.Max(s-1,0)],b=c[s],cc=c[s+1],d=c[Mathf.Min(s+2,c.Length-1)];
                var q=.5f*((2*b)+(-a+cc)*t+(2*a-5*b+4*cc-d)*t*t+(-a+3*b-3*cc+d)*t*t*t);pts.Add(new Vector3(q.x,0,q.y));}
            pts.Add(new Vector3(c[^1].x,0,c[^1].y));
            int n=pts.Count;var y=new float[n];for(int i=0;i<n;i++)y[i]=Mathf.Max(Base(pts[i].x,pts[i].z),.6f);
            var sm=new float[n];for(int i=0;i<n;i++){float s=0;int m=0;for(int k=-14;k<=14;k++){int j=Mathf.Clamp(i+k,0,n-1);s+=y[j];m++;}sm[i]=s/m;}
            float y0=track.At(track.Nearest(pts[0],out _)).y,y1=track.At(track.Nearest(pts[^1],out _)).y;
            for(int i=0;i<n;i++){float t=i/(float)(n-1);float end=Mathf.Max(1-Blend(0,.12f,t),Blend(.88f,1,t));sm[i]=Mathf.Lerp(sm[i],t<.5f?y0:y1,end);pts[i]=new Vector3(pts[i].x,sm[i],pts[i].z);}
            return gravel=pts.ToArray();
        }
        static float Nearest(Vector3[] line,float x,float z,out float y)
        {
            float best=float.MaxValue;y=0;var q=new Vector2(x,z);
            for(int i=1;i<line.Length;i++){Vector2 a=new(line[i-1].x,line[i-1].z),ab=new Vector2(line[i].x,line[i].z)-a;float t=Mathf.Clamp01(Vector2.Dot(q-a,ab)/Mathf.Max(ab.sqrMagnitude,1e-6f));
                float d=(a+ab*t-q).magnitude;if(d<best){best=d;y=Mathf.Lerp(line[i-1].y,line[i].y,t);}}
            return best;
        }
        // The causeway link: from the loop's start straight down to the mainline's first point at the quay.
        public static readonly Vector3 LinkTop=new(68.3f,FrontY-.075f,-55f);   // (the mainline draws 0.1 m over its line: level with the loop's 0.025 m asphalt)
        // (held at quay level until it clears the start straight's 12 m shoulder: it dropped 0.4 m inside it, docs/80 round 1)
        public static readonly Vector3 LinkHold=new(68.3f,FrontY-.075f,-69f);

        // The island's height with its roads: the land, then each road's shoulder flattened to the road (the loop 13 m
        // either side of its centre, blending out by 26 m; the gravel lane 4 m, by 11 m; the causeway link 6 m, by 14 m).
        public static float Height(float x,float z,Circuit track)
        {
            float h=Base(x,z);var p=new Vector3(x,0,z);
            float d=track.Nearest(p,out float off);var at=track.At(d);float rd=new Vector2(at.x-x,at.z-z).magnitude;
            h=Mathf.Lerp(h,at.y,1-Blend(13,26,rd));
            // the harbour front's town row stands on a level shelf inland of the road, the hill rising behind it
            // (its back edge sharp: a granite retaining wall stands there, TownWall; it was a 10 m bank of bare earth)
            float town=Blend(TownFrom-12,TownFrom,d)*(1-Blend(TownTo,TownTo+12,d))*(off<0?1:0)*(1-Blend(TownBack,TownBack+1.2f,rd));
            h=Mathf.Lerp(h,at.y,town);   // (level with the road: any higher and the land covers the road's inland half)
            // the Pit Stop's square, level with the start straight, a long grassy bank up to the hill (not a cut ledge)
            float sq=Blend(4,30,x)*(1-Blend(100,126,x))*Blend(-48,-44,z)*(1-Blend(-4,30,z))*Blend(10,14,rd);h=Mathf.Lerp(h,FrontY,sq);   // (never under the loop: the S-bend passes above it)
            // the harbour arms: stone piers at quay level, 9 m wide; the land drops inside their walls' cores (4-5.2 m out)
            // so none shows through the battered faces
            var q=new Vector2(x,z);float arm=Mathf.Min(PolylineDistance(NewBayviewPlan.WestArm,q),PolylineDistance(NewBayviewPlan.QuayArm,q));
            h=Mathf.Lerp(h,Mathf.Max(h,FrontY),1-Blend(4,5,arm));   // (only at the arms: a Max with -16 everywhere held the whole sea floor up at -16, R1-1)
            // (the lane gives way to the loop's road and runoff where it joins: its land pushed up through the hairpin's apex)
            // the hill farm's yard, level (docs/80 round 2)
            float fd=Vector2.Distance(q,NewBayviewPlan.Farm);if(fd<42)h=Mathf.Lerp(h,FarmY,1-Blend(14,40,fd));   // (a long blend: a short one cut a bare crescent into the hill)
            float gd=Nearest(GravelPoints(track),x,z,out float gy);h=Mathf.Lerp(h,gy,(1-Blend(4,11,gd))*Blend(10,14,rd));
            // the lighthouse's headland, levelled from the road out to the tower
            var lt=LighthouseAt(track);var lr=new Vector2(lightRoad.x,lightRoad.z);float lh=PolylineDistance(new[]{lr,new Vector2(lt.x,lt.z)},q);
            h=Mathf.Lerp(h,lightRoad.y,(1-Blend(7,13,lh))*Blend(10,14,rd));   // (not over the road: it climbs past the point)
            float ld=Mathf.Abs(x-LinkTop.x);if(z<LinkTop.z+4&&z>-90){float ly=Mathf.Lerp(LinkTop.y,0,Mathf.InverseLerp(LinkHold.z,-83.4f,z));h=Mathf.Lerp(h,ly,1-Blend(10,24,ld));}   // (a broad landform: on a 14 m one the link ran along a ridge, docs/80)
            return h;
        }

        // ---- stage 2: the harbour and the town
        public static void BuildTown(Circuit track)
        {
            var root=new GameObject("New Bayview harbour and town").transform;
            var granite=WorldLook.Kit("Harbour granite",new Color(.56f,.55f,.52f),WorldLook.Pattern.Stone,0,.1f,true,1.6f);
            // the harbour: a wall along the bay's shore, both faces of each arm, a rounded head on each
            Wall(root,NewBayviewPlan.Harbour,0,granite);
            foreach(var arm in new[]{NewBayviewPlan.WestArm,NewBayviewPlan.QuayArm}){Wall(root,arm,4.6f,granite);Wall(root,arm,-4.6f,granite);Head(root,arm,granite);}
            // railings along the quay's edge (the shore), lamps on the quay side of the road, benches looking out to sea
            var blue=new BayviewKit.Tint(Color.white,Toy.Hex(0x1d4f8a),Color.white,Color.white);
            Along(NewBayviewPlan.Harbour,6,1.2f,(at,yaw)=>BayviewKit.Spawn("promenade_rail",at,yaw,root,blue));
            for(float s=TownFrom+6;s<TownTo;s+=24) {
                var at=track.At(s);var r=track.Right(s);var f=track.Forward(s);float face=Mathf.Atan2(r.x,r.z)*Mathf.Rad2Deg;
                var lamp=at+r*10.5f;lamp.y=FrontY;if(Vector3.Distance(lamp,TowerSpot)<8)continue;   // (the clock tower's place)
                BayviewKit.Spawn("lamp_post",lamp,face,root,blue);
                var bench=at+r*11.5f+f*5;bench.y=FrontY;BayviewKit.Spawn("bench",bench,face+180,root);
            }
            // the town row: shops and terraces round the harbour front, each its own bold colour (Cornish and Scottish
            // harbour paint: docs/79), fronts to the road and the water
            var row=new (string id,float w,float d,int wall,int shutter,int awning,int door,string sign)[]{
                ("terrace_a",5.4f,8,0xe8735a,0xffffff,0xff4d5e,0x1d4f8a,null),("terrace_d",5.4f,8,0xf0c24a,0x1d4f8a,0x1d4f8a,0xd94040,null),
                ("cafe",9,8,0x5fb3c2,0xffffff,0xff4d5e,0x1d4f8a,"THE DAILY MILE"),("terrace_b",5.4f,8,0xd96a8c,0xffffff,0xffd23f,0x2e9e5b,null),
                ("terrace_c",5.4f,8,0xf5ead0,0x2e6fb5,0x2e6fb5,0x2e6fb5,null),("post_office",9,8,0xe2493a,0xffffff,0x3a7bd5,0xffffff,"POST OFFICE"),
                ("terrace_a",5.4f,8,0x7fc28e,0xffffff,0xff4d5e,0xffffff,null),("terrace_d",5.4f,8,0x4a7fc0,0xffffff,0xffd23f,0xffd23f,null),
                ("shop",9,8,0xf29a3a,0x1d4f8a,0x1fa37a,0x1d4f8a,"TIDES & TYRES"),("terrace_e",5.4f,8,0xb8e0d2,0xd94040,0xd94040,0xd94040,"FISH & CHIPS"),
                ("terrace_c",5.4f,8,0xe8b8c8,0x1d4f8a,0xff4d5e,0x1d4f8a,null),("shop",9,8,0x8a6ac0,0xffd23f,0xffd23f,0xffffff,"BAYVIEW PAINTS"),
                ("terrace_g",5.4f,8,0xf0d060,0x2e9e5b,0x2e9e5b,0x2e9e5b,"SURF SHACK"),("terrace_d",5.4f,8,0xe06048,0xffffff,0x3a7bd5,0x1d4f8a,null),
                ("terrace_b",5.4f,8,0x6fb0a0,0xffffff,0xffd23f,0xffffff,null),("terrace_c",5.4f,8,0xf7f0e2,0xe2493a,0xe2493a,0xe2493a,null)};
            int[] roofs={0x5f6b7a,0,0x4c5562,0xc4684c,0x5f6b7a,0,0x4c5562,0x5f6b7a};
            float s0=TownFrom+4;int k=0;
            foreach(var b in row) {
                float s=s0+b.w*.5f;if(s+b.w*.5f>TownTo)break;
                var at=track.At(s);var r=track.Right(s);var pos=at-r*(11.5f+b.d*.5f);pos.y=at.y+.12f;float yaw=Mathf.Atan2(r.x,r.z)*Mathf.Rad2Deg;
                var tint=new BayviewKit.Tint(Toy.Hex(b.wall),Toy.Hex(b.shutter),Toy.Hex(b.awning),Toy.Hex(b.door));int roof=roofs[k++%roofs.Length];if(roof!=0)tint.roof=Toy.Hex(roof);
                BayviewKit.Spawn(b.id,pos,yaw,root,tint,b.sign);
                if(b.id=="cafe"){Cafe=at-r*9.5f;CafeYaw=yaw;}if(b.sign=="BAYVIEW PAINTS"){Paint=at-r*9.5f;PaintYaw=yaw;}
                s0+=b.w+.15f;
            }
            // (then terraces to the arc's end, cycling the terrace types through the harbour paints)
            int[] walls={0xe8735a,0x4a7fc0,0xf0c24a,0x7fc28e,0xd96a8c,0x5fb3c2,0xf29a3a,0xe8b8c8,0x6fb0a0,0xf7f0e2};string[] kinds={"terrace_e","terrace_b","terrace_f","terrace_a","terrace_g","terrace_c","terrace_d"};
            for(int e=0;;e++) {
                float s=s0+2.7f;if(s+2.7f>TownTo)break;
                var at=track.At(s);var r=track.Right(s);var pos=at-r*15.5f;pos.y=at.y+.12f;float yaw=Mathf.Atan2(r.x,r.z)*Mathf.Rad2Deg;
                var tint=new BayviewKit.Tint(Toy.Hex(walls[e%walls.Length]),e%3==0?Toy.Hex(0x1d4f8a):Color.white,Toy.Hex(e%2==0?0xff4d5e:0xffd23f),Toy.Hex(e%2==0?0x1d4f8a:0xd94040));
                int roof=roofs[k++%roofs.Length];if(roof!=0)tint.roof=Toy.Hex(roof);
                BayviewKit.Spawn(kinds[e%kinds.Length],pos,yaw,root,tint);s0+=5.55f;
            }
            Cafe.y=Paint.y=FrontY;
            Paving(root,track);
            Landmarks(root,track);
            Debug.Log($"LITTLE_ROAD_NEW_BAYVIEW_TOWN buildings={k} arc={TownFrom:0}-{s0:0}");
        }

        // ---- stage 3: the landmarks, one in each direction (docs/79): the clock tower on the harbour front, the lifeboat
        // station on the west arm, the helter-skelter on its pier off the east beach, the lighthouse on the west point (it
        // stands behind Pip, AdventureGame) and the windmill on the summit (CoastalLandscape).
        // The summit's tower mill (Prop Forge landmarks: tower_mill, and its sails as their own piece, turning), facing
        // down over the harbour. Its hub stands 12.6 m up and 2.55 m out (landmarks.py HUB_UP, HUB_OUT).
        public static bool Windmill(System.Func<float,float,float> height)
        {
            if(!BayviewKit.Has("tower_mill")||!BayviewKit.Has("tower_mill_sails"))return false;
            var w=NewBayviewPlan.Windmill;var at=new Vector3(w.x,0,w.y);at.y=height(at.x,at.z)-.3f;
            var to=TowerSpot-at;float yaw=Mathf.Atan2(to.x,to.z)*Mathf.Rad2Deg;var rot=Quaternion.Euler(0,yaw,0);
            BayviewKit.Spawn("tower_mill",at,yaw,null,new BayviewKit.Tint(Toy.Hex(0xf4efe4),Toy.Hex(0x2bb5a8),Toy.Hex(0xff4d5e),Toy.Hex(0x1d4f8a)));
            var sails=BayviewKit.Spawn("tower_mill_sails",at+rot*new Vector3(0,12.6f,2.55f),yaw,BayviewKit.AnimatedRoot,new BayviewKit.Tint(Color.white,Toy.Hex(0xe2493a),Color.white,Color.white),solid:false);
            var spin=sails.AddComponent<KitSpin>();spin.kit=sails.transform;spin.axle=Vector3.forward;spin.degreesPerSecond=24;
            return true;
        }
        static Vector3 TowerSpot=>new(NewBayviewPlan.ClockTower.x,FrontY,NewBayviewPlan.ClockTower.y);
        static void Landmarks(Transform root,Circuit track)
        {
            if(BayviewKit.Has("clock_tower")) {
                var t=TowerSpot;var a=track.At(track.Nearest(t,out _));var d=a-t;BayviewKit.Spawn("clock_tower",t,Mathf.Atan2(d.x,d.z)*Mathf.Rad2Deg,root);
            }
            // (across the west arm, 70% down its first leg, its doors and slipway to the open sea)
            var arm=NewBayviewPlan.WestArm;var dir=(arm[1]-arm[0]).normalized;var at=arm[0]+(arm[1]-arm[0])*.7f;var o=new Vector2(dir.y,-dir.x);
            if(BayviewKit.Has("lifeboat_station"))BayviewKit.Spawn("lifeboat_station",new Vector3(at.x,FrontY,at.y),Mathf.Atan2(o.x,o.y)*Mathf.Rad2Deg,root);
            Pier(root,track);
