            var flags=WorldLook.Kit("Harbour front flagstones",new Color(.72f,.69f,.63f),WorldLook.Pattern.Stone,0,.12f,true,.8f);
            float Y(Vector3 v)=>Height(v.x,v.z,track)+.05f;
